from flask import Flask, render_template

print(__name__)
app = Flask(__name__)
site_name = "Track Finder"
tracks = [ 

    {"name": "Mount Eden Loop", "length": 2.0, "grade": "Easy", "stars" : 5, "image" : "data:image/jpeg;base64,"}, 

    {"name": "Coast to Coast Walkway", "length": 16.0, "grade": "Medium", "stars" : 2, "image" : "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT_2aoM_P_Z7-01peP7velbf_Rl3XSzKVovuaZvbC3SPWNXceX5zF40lW4&s=10"}, 

    {"name": "Karekare Falls", "length": 3.5, "grade": "Easy", "stars" : 1, "image": "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTh_5neOhsRxxV0u-2f1OmP-Gcng1qPtJ7m7KjI4zAWOw&s=10"} , 

    {"name": "Hillary Trail", "length": 70.0, "grade": "Hard", "stars" : 3, "image" : "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRR5jM9WZLB-Z7jrg5nzBc5lPmTswtgEh3wBeaHNb6Odw&s=10"},

    {"name" : "Puhinui Stream Forest Trail", "length" : 4.2, "grade" : "Easy", "stars" : 4, "image" : "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR2SI7KaYYKLVnUoeC3OJG0F0D3wRiFbiP3_hAw46yNl324u1xcQtE6l7k&s=10"} 
    
    

]
count = len(tracks)
if count == 0:
    message = "There are NO tracks!"
elif count == 1:
    message = "There's only a SINGULAR track!!!! T_T T_T"
else:
    message = "Yayyy there is 2 or more tracks!!! :>"


@app.route("/") 
def home(): 
    return render_template("home.html", site_name=site_name, count=count, message=message)

@app.route("/tracks") 
def tracks_page(): 
    return render_template("tracks.html", site_name=site_name, tracks=tracks)

@app.route("/cars")
def cars():
    return ""

@app.errorhandler(404) 
def page_not_found(e): 
    return render_template("404.html"), 404

if __name__ == "__main__": 

    app.run(debug=True, port=5000) 